

import React from 'react';

export default function Formgroup({ type, value, placeholder, onChange, className, required, ...rest }: React.InputHTMLAttributes<HTMLInputElement>) {
   return (
    <div>
     <input
       type={type}
       value={value}
       placeholder={placeholder}
       onChange={onChange}
       className={className}
       required={required}
       {...rest}
      />
    </div>
   )
}
