/* eslint-disable @typescript-eslint/no-unused-vars */
/* eslint-disable @typescript-eslint/no-explicit-any */
import { useState } from "react";
import FormGraup from "../components/FormGroup";
import { useNavigate, Link } from "@tanstack/react-router";
import axios from "axios";


const api = axios.create({
    baseURL: "http://localhost:8002/api/auth",
    headers: {
        "Content-Type": "application/json"
    },
    withCredentials: true
});

export default function LoginUser() {
    const [email, setEmail] = useState<string>("");
    const [password, setPassword] = useState<string>("");
    const [loading, setLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const navigate = useNavigate();

    const validateEmail = (): boolean => {
        const inputEmail = email.trim();
        if (!inputEmail) {
            setError("Email not found");
            return false;
        }
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(inputEmail)) {
            setError("Invalid email format");
            return false;
        }
        return true;
    };

    const validatePassword = (): boolean => {
        const inputPassword = password.trim();
        if (!inputPassword) {
            setError("Password cannot be empty");
            return false;
        }
        if (inputPassword.length < 6) {
            setError("Password must be at least 6 characters");
            return false;
        }
        return true;
    };

    const loginSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setError(null);

        if (!validateEmail() || !validatePassword()) {
            return;
        }

        try {
            setLoading(true);
            const response = await api.post('/login', {
                email: email.trim(),
                password: password.trim()
            });
            console.log(response.data)
            if (response.data?.error) {
                setError(response.data.error);
            } else {
                navigate({ to: "/" });
            }
        } catch (error: any) {
            setError("Network error or invalid credentials. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-50">
            <div className="w-full max-w-md p-8 bg-white rounded-lg shadow-md">
                <form onSubmit={loginSubmit} className="flex flex-col gap-5">
                    <h2 className="text-2xl font-bold text-center text-gray-800">Welcome Back</h2>

                    {error && (
                        <div className="p-3 text-sm text-red-600 bg-red-100 border border-red-200 rounded">
                            {error}
                        </div>
                    )}

                    {/* Email Input */}
                    <div className="flex flex-col gap-1.5">
                        <label className="text-sm font-medium text-gray-700">Email Address</label>
                        <FormGraup
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="name@example.com"
                            className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                            required
                        />
                    </div>

                    {/* Password Input */}
                    <div className="flex flex-col gap-1.5">
                        <label className="text-sm font-medium text-gray-700">Password</label>
                        <FormGraup
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="Enter your password"
                            className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                            required
                        />
                    </div>

                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full py-2.5 mt-2 text-white bg-blue-600 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50 transition-colors font-medium"
                    >
                        {loading ? "Logging in..." : "Login"}
                    </button>

                    <p className="text-sm text-center text-gray-600 mt-2">
                        Don&rsquo;t have an account?{" "}
                        <Link to="/login" className="text-blue-600 hover:underline font-medium">
                            login
                        </Link>
                    </p>
                </form>
            </div>
        </div>
    );
};